from itertools import permutations

raw = "_lugnw_f3mn4dgru3"

# No need to permute all 17 letters; too many! Let's try to find readable CTF-flags, prioritizing words like CTF, FLAG, CSAW etc.
# Let's try to brute force for 'flag', 'csaw', 'ctf', 'rev', 'win', 'fun', numbers

choices = set()

# Try flag as a prefix
for p in permutations(raw, 17):
    s = ''.join(p)
    if s.startswith('flag'):
        choices.add(s)
    elif 'flag' in s:
        choices.add(s)
    elif 'ctf' in s:
        choices.add(s)
    elif 'csaw' in s:
        choices.add(s)
    elif 'win' in s:
        choices.add(s)
    if len(choices) > 20:
        break
for c in choices:
    print('flag{' + c + '}')

